 private int dp(int value){return (int)(value*getResources().getDisplayMetrics().density);}
 @Override public void onCreate(Bundle state){super.onCreate(state);showApp(false);boolean handled=handle(getIntent());if(!handled)web.loadUrl(serverUrl()+"/");}
