 @SuppressWarnings("SetJavaScriptEnabled") private void showApp(boolean load){if(web!=null){web.stopLoading();web.destroy();}LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(0xff17232a);root.setOnApplyWindowInsetsListener((view,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(android.view.WindowInsets.Type.systemBars()|android.view.WindowInsets.Type.displayCutout());view.setPadding(bars.left,bars.top,bars.right,bars.bottom);}else view.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});
 LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(10),0,dp(6),0);ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.brand_logo);logo.setContentDescription("Logo Gửi Khuê Nhã");bar.addView(logo,new LinearLayout.LayoutParams(dp(26),dp(26)));TextView title=new TextView(this);title.setText("  Gửi Khuê Nhã");title.setTextSize(14);title.setTextColor(0xffefd3a0);bar.addView(title,new LinearLayout.LayoutParams(0,dp(40),1));Button reload=new Button(this);reload.setText("↻");reload.setContentDescription("Tải lại sổ tay");reload.setOnClickListener(v->web.reload());bar.addView(reload,new LinearLayout.LayoutParams(dp(48),dp(40)));Button settings=new Button(this);settings.setText("⚙");settings.setContentDescription("Tiện ích Android");settings.setOnClickListener(v->showSettings());bar.addView(settings,new LinearLayout.LayoutParams(dp(48),dp(40)));root.addView(bar);
 status=new TextView(this);status.setTextColor(0xffedcf90);status.setTextSize(12);status.setPadding(dp(12),dp(7),dp(12),dp(7));status.setVisibility(android.view.View.GONE);root.addView(status);progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(100);root.addView(progress,new LinearLayout.LayoutParams(-1,dp(3)));
 web=new WebView(this);web.setBackgroundColor(0xff17232a);WebSettings options=web.getSettings();options.setJavaScriptEnabled(true);options.setUserAgentString(options.getUserAgentString()+" GuiKhueNha/1.7");options.setDomStorageEnabled(true);options.setAllowFileAccess(false);options.setAllowContentAccess(false);options.setGeolocationEnabled(false);options.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);options.setSupportMultipleWindows(true);options.setJavaScriptCanOpenWindowsAutomatically(false);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);
 web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,String url){return route(Uri.parse(url));}@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){return request.isForMainFrame()&&route(request.getUrl());}@Override public void onPageStarted(WebView view,String url,android.graphics.Bitmap icon){progress.setVisibility(android.view.View.VISIBLE);status.setVisibility(android.view.View.GONE);}@Override public void onPageFinished(WebView view,String url){progress.setVisibility(android.view.View.GONE);CookieManager.getInstance().flush();WidgetSync.capture(MainActivity.this);if(redeeming&&web==view&&sameServer(Uri.parse(url))){redeeming=false;web.clearHistory();}}@Override public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame())showStatus("Chưa tải được sổ tay. Kiểm tra mạng hoặc chờ Render khởi động rồi bấm ↻.");}@Override public boolean onRenderProcessGone(WebView view,RenderProcessGoneDetail detail){if(recoveringWebView)return true;recoveringWebView=true;final WebView crashed=view;web=null;widgetHandler.post(()->{try{android.view.ViewParent parent=crashed.getParent();if(parent instanceof android.view.ViewGroup)((android.view.ViewGroup)parent).removeView(crashed);crashed.destroy();if(!isFinishing()&&!isDestroyed()){showApp(true);showStatus("Đã phục hồi giao diện sau khi WebView gặp lỗi. Nếu đăng nhập chưa hoàn tất, mở lại Kết nối Google.");}}catch(Exception error){showStatus("Không thể phục hồi giao diện. Đóng và mở lại ứng dụng.");}finally{recoveringWebView=false;}});return true;}});
 web.setWebChromeClient(new WebChromeClient(){@Override public void onProgressChanged(WebView view,int value){progress.setProgress(value);progress.setVisibility(value<100?android.view.View.VISIBLE:android.view.View.GONE);}@Override public boolean onCreateWindow(WebView view,boolean dialog,boolean gesture,Message result){if(!gesture)return false;WebView popup=new WebView(MainActivity.this);popup.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){if("about".equals(r.getUrl().getScheme()))return false;routePopup(r.getUrl());v.destroy();return true;}});((WebView.WebViewTransport)result.obj).setWebView(popup);result.sendToTarget();return true;}});
 web.setDownloadListener((url,agent,disposition,mime,length)->openExternal(Uri.parse(url)));root.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);root.requestApplyInsets();if(load)web.loadUrl(serverUrl()+"/");}
 private void showStatus(String text){status.setText(text);status.setVisibility(android.view.View.VISIBLE);}
 private boolean sameServer(Uri uri){try{return ServerAddress.normalize(uri.getScheme()+"://"+uri.getEncodedAuthority()).equals(serverUrl());}catch(Exception e){return false;}}
 private boolean route(Uri uri){if("guikhuenha".equals(uri.getScheme())&&"refresh".equals(uri.getHost())){if(web.getUrl()!=null&&sameServer(Uri.parse(web.getUrl())))WidgetSync.capture(this);return true;}if("guikhuenha".equals(uri.getScheme())){handle(new Intent(Intent.ACTION_VIEW,uri));return true;}if(sameServer(uri)){if("/auth/google".equals(uri.getPath())){startGoogleAuth();return true;}return false;}openExternal(uri);return true;}
 private void routePopup(Uri uri){if(sameServer(uri)){if("/auth/google".equals(uri.getPath()))startGoogleAuth();else web.loadUrl(uri.toString());}else openExternal(uri);}
 private void openExternal(Uri uri){if(!"https".equals(uri.getScheme())&&!"http".equals(uri.getScheme())){toast("Liên kết này không được hỗ trợ.");return;}try{new CustomTabsIntent.Builder().setShowTitle(true).build().launchUrl(this,uri);}catch(Exception first){try{startActivity(new Intent(Intent.ACTION_VIEW,uri));}catch(Exception second){showStatus("Cần trình duyệt để đăng nhập Google hoặc mở tài liệu bên ngoài.");}}}
 private String random(){byte[] value=new byte[32];new SecureRandom().nextBytes(value);return Base64.encodeToString(value,Base64.URL_SAFE|Base64.NO_WRAP|Base64.NO_PADDING);}
 private void startGoogleAuth(){try{long now=System.currentTimeMillis();if(now-lastAuthStart<2000L)return;lastAuthStart=now;String verifier=random(),state=random(),challenge=Base64.encodeToString(MessageDigest.getInstance("SHA-256").digest(verifier.getBytes(StandardCharsets.US_ASCII)),Base64.URL_SAFE|Base64.NO_WRAP|Base64.NO_PADDING);getSharedPreferences("khue_nha_auth",0).edit().putString("verifier",verifier).putString("state",state).putString("origin",serverUrl()).putLong("expires",System.currentTimeMillis()+900000L).apply();Uri uri=Uri.parse(serverUrl()+"/auth/google").buildUpon().appendQueryParameter("mobile_challenge",challenge).appendQueryParameter("mobile_state",state).build();showStatus("Chọn tài khoản Google trong trình duyệt, sau đó bấm Trở về Gửi Khuê Nhã.");openExternal(uri);}catch(Exception e){showStatus("Chưa bắt đầu được đăng nhập. Hãy thử lại.");}}
 private boolean handle(Intent intent){if(intent==null)return false;Uri uri=intent.getData();if(uri!=null&&"guikhuenha".equals(uri.getScheme())&&"auth".equals(uri.getHost())){intent.setData(null);android.content.SharedPreferences pending=getSharedPreferences("khue_nha_auth",0);String code=uri.getQueryParameter("code"),state=uri.getQueryParameter("state"),expected=pending.getString("state",""),verifier=pending.getString("verifier","");if(code==null||!code.matches("[A-Za-z0-9_-]{43}")||state==null||!MessageDigest.isEqual(state.getBytes(StandardCharsets.UTF_8),expected.getBytes(StandardCharsets.UTF_8))||!serverUrl().equals(pending.getString("origin",""))||pending.getLong("expires",0)<System.currentTimeMillis()||verifier.isEmpty()){showStatus("Phiên đăng nhập trên app hết hạn hoặc không khớp. Bấm Kết nối Google để thử lại.");return true;}pending.edit().clear().apply();redeeming=true;String body="code="+Uri.encode(code)+"&verifier="+Uri.encode(verifier);web.postUrl(serverUrl()+"/auth/mobile/redeem",body.getBytes(StandardCharsets.UTF_8));return true;}
 String task=intent.getStringExtra("open_task");if(task!=null){web.loadUrl(serverUrl()+"/?task="+Uri.encode(task));intent.removeExtra("open_task");return true;}if(uri==null||!"guikhuenha".equals(uri.getScheme())||!"reminders".equals(uri.getHost()))return false;intent.setData(null);try{JSONObject snapshot=ReminderStore.validate(uri.getQueryParameter("data"));new AlertDialog.Builder(this).setTitle("Nhận bản nhắc công việc?").setMessage("Sổ tay: "+snapshot.optString("owner")+"\n"+snapshot.getJSONArray("tasks").length()+" việc. Thay bản nhắc cũ trên máy này.").setPositiveButton("Nhận & đặt giờ nhắc",(d,w)->{ReminderScheduler.cancel(this);((android.app.NotificationManager)getSystemService(NOTIFICATION_SERVICE)).cancelAll();if(ReminderStore.save(this,snapshot)){ReminderScheduler.schedule(this);TaskWidget.updateAll(this);permission();toast("Đã nhận bản nhắc. Gửi lại sau khi sửa công việc.");}else toast("Không lưu được bản nhắc.");}).setNegativeButton("Hủy",null).show();}catch(Exception e){toast("Bản nhắc không hợp lệ. Hãy gửi lại từ sổ tay.");}return false;}
 private void showSettings(){LinearLayout layout=new LinearLayout(this);layout.setOrientation(LinearLayout.VERTICAL);layout.setPadding(dp(18),dp(12),dp(18),dp(12));TextView server=new TextView(this);server.setText("Phiên bản 1.7 · "+serverUrl()+"\nCông việc mở trong app. Google và tài liệu ngoài dùng trình duyệt.");server.setTextSize(12);layout.addView(server);addButton(layout,"Kết nối / đổi tài khoản Google",()->startGoogleAuth());addButton(layout,"Đổi địa chỉ máy chủ",()->configureServer());connectionState=new TextView(this);connectionState.setTextSize(12);layout.addView(connectionState);addButton(layout,"Kiểm tra Render / DB",()->checkConnection());addButton(layout,"Bật quyền thông báo",()->permission());addButton(layout,"Ghim widget màn hình chính",()->pinWidget());addButton(layout,"Xóa bản nhắc trên điện thoại",()->new AlertDialog.Builder(this).setTitle("Xóa bản nhắc trên máy?").setMessage("Hủy nhắc và xóa snapshot; không xóa dữ liệu trên MongoDB.").setPositiveButton("Xóa",(d,w)->{ReminderScheduler.cancel(this);ReminderStore.clear(this);((android.app.NotificationManager)getSystemService(NOTIFICATION_SERVICE)).cancelAll();TaskWidget.updateAll(this);toast("Đã xóa bản nhắc.");}).setNegativeButton("Hủy",null).show());ScrollView scroll=new ScrollView(this);scroll.addView(layout);new AlertDialog.Builder(this).setTitle("Tiện ích Android").setView(scroll).setPositiveButton("Đóng",null).show();}
 private void configureServer(){EditText input=new EditText(this);input.setSingleLine(true);input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);input.setHint("https://ten-app.onrender.com");input.setText(serverUrl());LinearLayout box=new LinearLayout(this);box.setPadding(35,12,35,0);box.addView(input,new LinearLayout.LayoutParams(-1,-2));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Máy chủ của bạn").setMessage("Dán URL Render đã deploy. Khi đổi máy chủ, bản nhắc trên điện thoại sẽ được xóa để tránh nhầm dữ liệu.").setView(box).setPositiveButton("Lưu địa chỉ",null).setNegativeButton("Hủy",null).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(w->{try{String next=normalizeOrigin(input.getText().toString());if(!next.equals(serverUrl())){WidgetSync.clear(this);ReminderScheduler.cancel(this);ReminderStore.clear(this);((android.app.NotificationManager)getSystemService(NOTIFICATION_SERVICE)).cancelAll();getSharedPreferences("khue_nha_server",0).edit().putString("origin",next).apply();TaskWidget.updateAll(this);}dialog.dismiss();showApp(true);toast("Đã lưu địa chỉ. Mở sổ tay để đăng nhập Google.");}catch(Exception e){input.setError(e.getMessage());}}));dialog.show();}
 private void permission(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},33);else toast("Quyền thông báo đã sẵn sàng. Kiểm tra thêm âm thanh/kênh thông báo trong cài đặt Android.");}
 private void pinWidget(){if(Build.VERSION.SDK_INT>=26){AppWidgetManager manager=getSystemService(AppWidgetManager.class);if(manager.isRequestPinAppWidgetSupported()){manager.requestPinAppWidget(new ComponentName(this,TaskWidget.class),null,null);return;}}toast("Nhấn giữ màn hình chính → Tiện ích → Gửi Khuê Nhã để thêm widget.");}
 private void addButton(LinearLayout layout,String text,Runnable action){Button button=new Button(this);button.setText(text);button.setOnClickListener(v->action.run());layout.addView(button);}
 private void checkConnection(){if(checking){toast("Đang kiểm tra. Vui lòng chờ máy chủ khởi động.");return;}checking=true;String origin=serverUrl();connectionState.setText("Đang kiểm tra máy chủ… Render Free có thể cần khoảng một phút để khởi động.");new Thread(()->{String result;HttpURLConnection connection=null;try{connection=(HttpURLConnection)new URL(origin+"/api/health").openConnection();connection.setConnectTimeout(15000);connection.setReadTimeout(90000);connection.setInstanceFollowRedirects(false);connection.setRequestProperty("Accept","application/json");int code=connection.getResponseCode();if(code!=200)result="Máy chủ trả HTTP "+code+". Kiểm tra trạng thái deploy và Logs trên Render.";else{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream stream=connection.getInputStream()){byte[] chunk=new byte[2048];int n;while((n=stream.read(chunk))!=-1){if(bytes.size()+n>16384)throw new Exception("Response too large");bytes.write(chunk,0,n);}}JSONObject health=new JSONObject(bytes.toString("UTF-8"));boolean database="ready".equals(health.optString("status"))&&"mongodb".equals(health.optString("storage"));result=database?"Render hoạt động · MongoDB đã sẵn sàng.":"Render phản hồi nhưng MongoDB chưa sẵn sàng. Kiểm tra URI, mật khẩu và IP Access List.";result+=health.optBoolean("googleConfigured")?"\nĐã có cấu hình Google trên máy chủ; bấm Kết nối Google để cấp quyền.":"\nGoogle chưa được cấu hình trên Render. Cần GOOGLE_CLIENT_ID và GOOGLE_CLIENT_SECRET cùng khóa mã hóa/DB.";}}catch(Exception error){result="Chưa kiểm tra được kết nối. Có thể Render đang khởi động hoặc mạng chưa sẵn sàng. Mở URL Render trong trình duyệt để kiểm tra rồi thử lại.";}finally{if(connection!=null)connection.disconnect();}String message=result;runOnUiThread(()->{checking=false;if(!isFinishing()&&!isDestroyed()&&origin.equals(serverUrl()))connectionState.setText(message);});}).start();}
 private void toast(String message){Toast.makeText(this,message,Toast.LENGTH_LONG).show();}
